class TTLLRUCache {
  constructor(capacity) { this.capacity = Math.max(0, capacity); this.entries = new Map(); }
  _purgeExpired(nowMs) { for (const [k, v] of this.entries) if (v.expiresAt <= nowMs) this.entries.delete(k); }
}

class RateLimiter {
  constructor(limit, windowMs) { this.limit = limit; this.windowMs = windowMs; this.hits = new Map(); }
  allow(uid, nowMs) { const q = (this.hits.get(uid) || []).filter(t => t >= nowMs - this.windowMs); if (q.length >= this.limit) return false; q.push(nowMs); this.hits.set(uid, q); return true; }
}
